local UserInputService = game:GetService("UserInputService")
local AssetService = game:GetService("AssetService")

local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local VAL = {}
for i = 1, #ALPHABET do
	VAL[string.byte(ALPHABET, i)] = i - 1
end
local SKIP = 63

local ContentProvider = game:GetService("ContentProvider")
local TweenService = game:GetService("TweenService")

-- ฟังก์ชันโหลดเพลงและแปลงเป็น ID ของ Roblox
local function loadCustomAudio(url, fileName)
	local soundId = ""
	local success, err = pcall(function()
		if writefile and getcustomasset then
			if not isfile(fileName) then
				local audioData = game:HttpGet(url)
				writefile(fileName, audioData)
			end
			soundId = getcustomasset(fileName)
		end
	end)
	
	if not success or soundId == "" then
		warn("โหลดเสียงไม่สำเร็จ (Executor อาจไม่รองรับ getcustomasset):", err)
		return nil
	end

	local sound = Instance.new("Sound")
	sound.SoundId = soundId
	sound.Looped = true -- ตั้งค่าให้เล่นวนลูป
	sound.Volume = 1 -- ความดังเริ่มต้น (ปรับได้ตามต้องการ)
	sound.Parent = workspace

	-- บังคับรอจนกว่าตัวเกมจะโหลดไฟล์เสียงเสร็จสมบูรณ์
	ContentProvider:PreloadAsync({ sound })
	return sound
end

