			StartAt = 0,
			StartX = 0,
			StartY = 0,
			MoveX = 0,
			MoveY = 0,
			Angle = 45,
			Active = false,
		})
	end

	local function respawnMeteor(meteor, now)
		local angle = math.rad(meteorRng:NextNumber(28, 62))
		local distance = meteorRng:NextNumber(0.85, 1.45)
		meteor.StartX = meteorRng:NextNumber(-0.15, 1.05)
		meteor.StartY = meteorRng:NextNumber(-0.45, 0.25)
		meteor.MoveX = math.cos(angle) * distance
		meteor.MoveY = math.sin(angle) * distance
		meteor.Angle = math.deg(angle)
		meteor.Length = meteorRng:NextNumber(90, 175)
		meteor.Speed = meteorRng:NextNumber(0.85, 1.65)
		meteor.StartAt = now + meteorRng:NextNumber(0.15, 1.35)
		meteor.Active = true
		meteor.Trail.Visible = false
		meteor.Head.Visible = false
	end

	local size = W * H * 4
	local buf = buffer.create(size)
	local function clear()
		buffer.fill(buf, 0, 0, size)
		for o = 3, size - 1, 4 do
			buffer.writeu8(buf, o, 255)
		end
	end

	local function applyFrame(str)
		local n = #str
		local i, pos = 1, 0
		while i <= n do
			local v = VAL[string.byte(str, i)]
			local c = VAL[string.byte(str, i + 1)]
			i += 2
			local count
			if c == 62 then
				count = VAL[string.byte(str, i)] * 64 + VAL[string.byte(str, i + 1)]
				i += 2
			else
				count = c + 1
			end
			if v ~= SKIP then
				local col = palette[v + 1]
				local r, g, b = col[1], col[2], col[3]
				local last = math.min((pos + count - 1) * 4, size - 4)
				for o = pos * 4, last, 4 do
					buffer.writeu8(buf, o, r)
					buffer.writeu8(buf, o + 1, g)
					buffer.writeu8(buf, o + 2, b)
				end
			end
			pos += count
		end
	end


	local alive = true
	local connection
	local inputConnection	
	local continueReady = false
	local continueRequested = false
    local musicFading = false
	local continueRequestedAt = 0
	local started = os.clock()
	if introMusic then
		introMusic:Play()
	end
	
	local current = 0
	local lastId
	local clipDoneAt = seqCount / DATA.FPS

	local function smooth(a, b, t)
		local x = math.clamp((t - a) / (b - a), 0, 1)
		return x * x * (3 - 2 * x)
	end

	local function finish()
		if not alive then return end
		alive = false
		
		if connection then connection:Disconnect() end
		if inputConnection then inputConnection:Disconnect() end
		if img then img:Destroy() end
		if gui then gui:Destroy() end
	end

	local function setSwordTransparency(value)
		for _, obj in ipairs({swordGrip, pommel, swordGuard, swordBlade, swordTip}) do
			obj.BackgroundTransparency = value
		end
		swordStroke.Transparency = math.clamp(value + 0.15, 0, 1)
	end

	local function setStoneTransparency(value)
		stone.BackgroundTransparency = value
		stoneStroke.Transparency = math.clamp(value + 0.12, 0, 1)
		stoneHighlight.BackgroundTransparency = math.clamp(value + 0.08, 0, 1)
		stoneCrack.BackgroundTransparency = math.clamp(value + 0.1, 0, 1)
	end

	local function hideSceneObjects()
		stage.Visible = false
		stone.Visible = false
		sword.Visible = false
		leftInfo.Visible = false
		rightTitle.Visible = false
		centerHalo.Visible = false
	end

	local shakeOffset = Vector2.zero
	local baseBackdropPosition = backdrop.Position


	inputConnection = UserInputService.InputBegan:Connect(function(input)
		if not alive or not continueReady or continueRequested then return end
		local inputType = input.UserInputType
		local isKeyboard = inputType == Enum.UserInputType.Keyboard
		local isClick = inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch
		if isKeyboard or isClick then
			continueRequested = true
			continueRequestedAt = os.clock() - started
		end
	end)

	connection = RunService.RenderStepped:Connect(function()
		if not alive then return end
		local t = os.clock() - started

		-- Keep the original clip untouched until its final encoded frame has played.
		if t < clipDoneAt then
			local wave = math.sin(t * 2.4)
			local drift = math.sin(t * 0.85) * 0.035
				local target = math.min(math.floor(t * DATA.FPS) + 1, seqCount)
			while current < target do
				current += 1
				if current == 1 then
					clear()
					lastId = nil
				end
				local id = sequence[current]
				if id ~= lastId then
					applyFrame(frames[id])
					lastId = id
				end
				if current == target then
					local writeOk, writeErr = pcall(function()
						img:WritePixelsBuffer(Vector2.zero, Vector2.new(W, H), buf)
					end)
					if not writeOk then
						warn("ClipPlayer: frame write failed", writeErr)
						finish()
						return
					end
				end
			end
			return
		end

		-- 0.5s after the clip ends, dissolve the clip and its background.
		local dissolve = smooth(clipDoneAt + 0.5, clipDoneAt + 1.1, t)
		image.ImageTransparency = dissolve
		imageStroke.Transparency = 0.82 + dissolve * 0.18
		backdrop.BackgroundTransparency = dissolve
		if dissolve >= 1 then
			stage.Visible = false
		end

		-- The stone fades in 0.5s after the clip has completely dissolved.
		local stoneStart = clipDoneAt + 1.6
		local stoneIn = smooth(stoneStart, stoneStart + 0.7, t)
		if t >= stoneStart then
			stone.Visible = true
			setStoneTransparency(1 - stoneIn)
		end

		-- Sword falls point-first into the center of the stone.
		local swordStart = stoneStart + 0.72
		local swordLand = swordStart + 0.62
		local swordDrop = smooth(swordStart, swordLand, t)
		if t >= swordStart then
			sword.Visible = true
			sword.Position = UDim2.new(0.5, 0, -0.28 + swordDrop * 0.70, 0)
			sword.Rotation = -7 + swordDrop * 7
			setSwordTransparency(1 - smooth(swordStart, swordStart + 0.16, t))
		end

		-- A brief impact shake, strongest immediately after the sword lands.
		local shakeDuration = 0.28
		local shakePower = 10 * (1 - smooth(swordLand, swordLand + shakeDuration, t))
		if t >= swordLand and t < swordLand + shakeDuration then
			local phase = (t - swordLand) * 95
			backdrop.Position = UDim2.new(0, math.sin(phase) * shakePower, 0, math.cos(phase * 0.83) * shakePower)
		else
			backdrop.Position = UDim2.new(0, 0, 0, 0)
		end

		-- Left credits appear first and gently move as a wave.
		local leftStart = swordLand + 0.18
		local leftFade = smooth(leftStart, leftStart + 0.48, t)
		if t >= leftStart then
			leftInfo.Visible = true
			centerHalo.Visible = true
			haloStroke.Transparency = 0.55 + 0.22 * math.sin(t * 2.8)
			centerHalo.Size = UDim2.fromOffset(190 + 12 * math.sin(t * 2.2), 190 + 12 * math.sin(t * 2.2))
			leftInfo.TextTransparency = 1 - leftFade
			local wave = math.sin((t - leftStart) * 4.2) * 5
			leftInfo.Position = UDim2.new(0.075, 0, 0.5, wave * 0.45)
		end

		-- Right-side title appears 0.7s after the left-side credits begin.
		local rightStart = leftStart + 0.7
		local rightFade = smooth(rightStart, rightStart + 0.5, t)
		if t >= rightStart then
			rightTitle.Visible = true
			rightTitle.TextTransparency = 1 - rightFade
			titleStroke.Transparency = 1 - rightFade * 0.72
		end

		-- Keep the sword embedded and the scene alive until the player interacts.
		local promptStart = rightStart + 0.5
		if t >= promptStart then
			continuePrompt.Visible = true
			local promptFade = smooth(promptStart, promptStart + 0.65, t)
			continueReady = t >= swordLand + 0.05
			continuePrompt.TextTransparency = 1 - promptFade * (0.82 + 0.12 * math.sin(t * 2.6))
		end

		-- Randomized meteor shower. The glowing head is positioned at the
		-- leading end of its own trail, so both stay aligned while falling.
		if t >= swordLand then
			for _, meteor in ipairs(meteors) do
				if not meteor.Active then
					respawnMeteor(meteor, swordLand)
				end
				if t >= meteor.StartAt then
					local elapsed = t - meteor.StartAt
					local progress = elapsed * meteor.Speed
					if progress >= 1.25 then
						respawnMeteor(meteor, t)
					else
						local x = meteor.StartX + meteor.MoveX * progress
						local y = meteor.StartY + meteor.MoveY * progress
						local fadeIn = math.clamp(progress / 0.09, 0, 1)
						local fadeOut = math.clamp((1.25 - progress) / 0.2, 0, 1)
						local alpha = math.min(fadeIn, fadeOut)
						local halfLength = meteor.Length * 0.5
						local dirX = math.cos(math.rad(meteor.Angle))
						local dirY = math.sin(math.rad(meteor.Angle))

						meteor.Trail.Visible = true
						meteor.Head.Visible = true
						meteor.Trail.Size = UDim2.fromOffset(meteor.Length, 2)
						meteor.Trail.Rotation = meteor.Angle
						meteor.Trail.Position = UDim2.fromScale(
							x - (dirX * halfLength / math.max(backdrop.AbsoluteSize.X, 1)),
							y - (dirY * halfLength / math.max(backdrop.AbsoluteSize.Y, 1))
						)
						meteor.Head.Position = UDim2.fromScale(x, y)
						meteor.Trail.BackgroundTransparency = 1 - alpha * 0.88
						meteor.Head.BackgroundTransparency = 1 - alpha
					end
				else
					meteor.Trail.Visible = false
					meteor.Head.Visible = false
				end
			end
		end

		if continueRequested then
			if introMusic and not musicFading then
				musicFading = true
				local fadeTween = TweenService:Create(
					introMusic,
					TweenInfo.new(0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
					{ Volume = 0 }
				)
				fadeTween:Play()
				fadeTween.Completed:Connect(function()
					introMusic:Stop()
					introMusic:Destroy()
				end)
			end		
			local fade = smooth(continueRequestedAt, continueRequestedAt + 0.35, t)
			backdrop.BackgroundTransparency = fade
			leftInfo.TextTransparency = math.max(leftInfo.TextTransparency, fade)
			rightTitle.TextTransparency = math.max(rightTitle.TextTransparency, fade)
			titleStroke.Transparency = math.max(titleStroke.Transparency, fade)
			continuePrompt.TextTransparency = math.max(continuePrompt.TextTransparency, fade)
			centerHalo.Visible = false
			setStoneTransparency(fade)
			setSwordTransparency(fade)
			for _, meteor in ipairs(meteors) do
				meteor.Trail.BackgroundTransparency = math.max(meteor.Trail.BackgroundTransparency, fade)
				meteor.Head.BackgroundTransparency = math.max(meteor.Head.BackgroundTransparency, fade)
			end
			if fade >= 1 then
				finish()
			  	local j = Instance.new("ScreenGui")
	              j.Name = "Fi"
	              j.Parent = playerGui
			end
		end

	end)
end

